import test from 'node:test';import assert from 'node:assert/strict';import {readFile,readdir} from 'node:fs/promises';import {createHash} from 'node:crypto';import {PGlite} from '@electric-sql/pglite';import YAML from 'yaml';
test('migrations run on PostgreSQL and enforce exclusive territories and ledger references',async()=>{const db=new PGlite();try{for(const name of(await readdir(new URL('../migrations/',import.meta.url))).sort())await db.exec(await readFile(new URL('../migrations/'+name,import.meta.url),'utf8'));await db.query("INSERT INTO partners(id,business_name,owner_name,owner_email,timezone,commission_pct,status) VALUES('00000000-0000-4000-8000-000000000001','Demo','Owner','demo@example.invalid','UTC',10,'active')");await db.query("INSERT INTO territories VALUES('00000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000001','00001')");await assert.rejects(()=>db.query("INSERT INTO territories VALUES('00000000-0000-4000-8000-000000000003','00000000-0000-4000-8000-000000000001','00001')"),/unique/);}finally{await db.close();}});
test('legacy funnel is byte-for-byte preserved',async()=>{const manifest=JSON.parse(await readFile(new URL('./legacy-hashes.json',import.meta.url),'utf8'));for(const[path,hash]of Object.entries(manifest))assert.equal(createHash('sha256').update(await readFile(new URL('../../'+path,import.meta.url))).digest('hex'),hash,path);});
test('blueprint retains the existing static service and keeps production SMS off',async()=>{const y=YAML.parse(await readFile(new URL('../../render.yaml',import.meta.url),'utf8'));assert.equal(y.services[0].name,'local-service-insider');assert.equal(y.services[0].runtime,'static');assert.equal(y.services[0].buildCommand,'');assert.equal(y.services.find(s=>s.name==='turf-tick').schedule,'*/5 * * * *');assert.equal(y.services.find(s=>s.name==='turf-api').envVars.find(e=>e.key==='SMS_ENABLED').value,'false');});
